deleteAfterAwait = async function(key, prom) {
  var err, result;
  try {
    result = (await prom);
  } catch (error) {
    // log "deleteAfterAwait - resolved to result!"
    // olog {result}
    err = error;
    log("deleteAfterAwait - exception thrown!");
  }
  // olog {err}
  requestToPromise.delete(key);
};

//###########################################################
requestExecute = async function(url, options, retryOn401) {
  var err, errorMessage, response;
  try {
    response = (await fetch(url, options));
  } catch (error) {
    err = error;
    throw new Error("Network Error: " + err.message);
  }
  //# return void on 204
  if (response.status === 204) {
    return;
  }
  //# return response body on 200 - should always be JSON
  if (response.status === 200) {
    try {
      return (await response.json());
    } catch (error) {
      err = error;
      throw new Error("ResultParsing Error: " + err.message);
    }
  }
  
  //# Any other Error will not be "OK" - and might have an error Messge for us...
  if (response.status === 401 && retryOn401) {
    try {
      await accM.assertAuthorization();
    } catch (error) {
      err = error;
      throw new Error(`Authorization could not be established! ${err.message}`);
    }
    return (await requestExecute(url, options, false));
    throw new Error("Authorization issue, but refresshed session, and retried :-(!");
  }
  try {
    errorMessage = (await response.text());
  } catch (error) {
    err = error;
    throw new Error("ErrorParsing Error: " + err.message);
  }
  throw new Error(errorMessage);
};

//###########################################################
request = async function(url, args, retryOn401) {
  var bodyStr, key, options, prom;
  log("request " + url);
  bodyStr = JSON.stringify(args);
  key = url + bodyStr;
  if (requestToPromise.has(key)) {
    return (await requestToPromise.get(key));
  }
  options = {
    method: 'POST',
    mode: 'cors',
    body: bodyStr,
    headers: {
      'Content-Type': 'application/json'
    }
  };
  prom = requestExecute(url, options, retryOn401);
  requestToPromise.set(key, prom);
  deleteAfterAwait(key, prom);
  return (await prom);
};

